import {
  Timestamps2
} from "./repository-cache-qfa1cgps.js";

// src/credential/sql.ts
import { integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
var CredentialTable2 = sqliteTable("credential", {
  id: text().$type().primaryKey(),
  integration_id: text().$type(),
  label: text().notNull(),
  value: text({ mode: "json" }).$type().notNull(),
  connector_id: text(),
  method_id: text(),
  active: integer({ mode: "boolean" }),
  ...Timestamps2
});

export { CredentialTable2 };
